#!/usr/bin/env python3
"""Prepare and submit Quantum ESPRESSO force runs generated by phonopy.

Run ``python phonopy_qe.py`` for an interactive menu, or use ``prepare`` and
``submit`` subcommands. Only the Python standard library is required.
"""

from __future__ import annotations

import argparse
from datetime import datetime, timezone
import re
import shutil
import subprocess
import sys
from pathlib import Path


def ask(prompt: str, default: str | None = None) -> str:
    suffix = f" [{default}]" if default else ""
    value = input(f"{prompt}{suffix}: ").strip()
    return value or (default or "")


def yaml_scalar(value: object) -> str:
    text = str(value)
    if not text or re.search(r"[:#\[\]{},&*!|>'\"%@`\n]", text) or text.strip() != text:
        return "'" + text.replace("'", "''") + "'"
    return text


def write_yaml(path: Path, data: dict) -> None:
    # Keep reports human-readable without requiring PyYAML.
    lines = []
    for key, value in data.items():
        if isinstance(value, list):
            lines.append(f"{key}:")
            for item in value:
                if isinstance(item, dict):
                    first, *rest = item.items()
                    lines.append(f"  - {first[0]}: {yaml_scalar(first[1])}")
                    lines.extend(f"    {k}: {yaml_scalar(v)}" for k, v in rest)
                else:
                    lines.append(f"  - {yaml_scalar(item)}")
        else:
            lines.append(f"{key}: {yaml_scalar(value)}")
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def geometry_cards(text: str, source: Path) -> tuple[str, int]:
    """Return the phonopy cell/species/positions cards, including positions count."""
    lines = text.splitlines()
    starts = {}
    for i, line in enumerate(lines):
        m = re.match(r"^\s*(CELL_PARAMETERS|ATOMIC_SPECIES|ATOMIC_POSITIONS)\b", line, re.I)
        if m:
            starts[m.group(1).upper()] = i
    if set(starts) != {"CELL_PARAMETERS", "ATOMIC_SPECIES", "ATOMIC_POSITIONS"}:
        raise ValueError(f"{source} must contain CELL_PARAMETERS, ATOMIC_SPECIES and ATOMIC_POSITIONS")

    def card_end(start: int) -> int:
        for i in range(start + 1, len(lines)):
            if re.match(r"^\s*(?:CELL_PARAMETERS|ATOMIC_SPECIES|ATOMIC_POSITIONS|K_POINTS|ADDITIONAL\w*)\b", lines[i], re.I):
                return i
        return len(lines)

    pos_start = starts["ATOMIC_POSITIONS"]
    pos_end = card_end(pos_start)
    pos_rows = [line for line in lines[pos_start + 1:pos_end]
                if line.strip() and not line.lstrip().startswith("!")]
    if not pos_rows:
        raise ValueError(f"No atomic positions found in {source}")

    # Include comments immediately preceding cards, such as phonopy's ! ibrav=0,nat=... note.
    def block(name: str) -> list[str]:
        start = starts[name]
        end = card_end(start)
        prefix = start
        while prefix > 0 and (not lines[prefix - 1].strip() or lines[prefix - 1].lstrip().startswith("!")):
            prefix -= 1
        return lines[prefix:end]

    return "\n".join(block("CELL_PARAMETERS") + block("ATOMIC_SPECIES") + block("ATOMIC_POSITIONS")), len(pos_rows)


def merge_input(template: str, displaced: str, source: Path) -> str:
    cards, nat = geometry_cards(displaced, source)
    lines = template.splitlines()
    # Remove the template's old structure cards; preserve unrelated cards/settings.
    card_re = re.compile(r"^\s*(CELL_PARAMETERS|ATOMIC_SPECIES|ATOMIC_POSITIONS)\b", re.I)
    starts = [i for i, line in enumerate(lines) if card_re.match(line)]
    for start in reversed(starts):
        end = start + 1
        while end < len(lines) and not re.match(r"^\s*(?:CELL_PARAMETERS|ATOMIC_SPECIES|ATOMIC_POSITIONS|K_POINTS|CONSTRAINTS|OCCUPATIONS|ATOMIC_FORCES|HUBBARD)\b", lines[end], re.I):
            end += 1
        del lines[start:end]
    template = "\n".join(lines).rstrip()

    def set_assignment(section: str, key: str, value: str) -> None:
        nonlocal template
        match = re.search(rf"(?ims)(^\s*&{section}\b.*?^\s*/)", template)
        if not match:
            raise ValueError(f"Unit-cell input is missing &{section.upper()} namelist")
        body = match.group(1)
        assignment = re.compile(rf"(?im)^\s*{re.escape(key)}\s*=.*?(?:,\s*(?:!.*)?$|\s*(?:!.*)?$)")
        if assignment.search(body):
            body = assignment.sub(f"  {key} = {value},", body, count=1)
        else:
            body = re.sub(r"(?im)(^\s*/)", f"  {key} = {value},\n\\1", body, count=1)
        template = template[:match.start(1)] + body + template[match.end(1):]

    set_assignment("SYSTEM", "nat", str(nat))
    return template + "\n\n" + cards + "\n"


def set_job_name(text: str, name: str) -> str:
    patterns = [
        (r"(?im)^(\s*#SBATCH\s+--job-name=).+$", rf"\g<1>{name}"),
        (r"(?im)^(\s*#SBATCH\s+-J\s+).+$", rf"\g<1>{name}"),
        (r"(?im)^(\s*#PBS\s+-N\s+).+$", rf"\g<1>{name}"),
        (r"(?im)^(\s*#BSUB\s+-J\s+).+$", rf"\g<1>{name}"),
    ]
    for pattern, replacement in patterns:
        text = re.sub(pattern, replacement, text)
    return text


def set_qe_filenames(text: str, input_name: str) -> str:
    """Point pw.x at the case input and the common output filename."""
    output_name = "supercell.out"
    updated = []
    for line in text.splitlines():
        if re.search(r"\bpw\.x\b", line):
            line = re.sub(r"(?<=\s)-in\s+\S+", f"-in {input_name}", line)
            # QE scripts commonly use shell redirection after the pw.x command.
            line = re.sub(r"(\s>\s*)\S+", rf"\g<1>{output_name}", line, count=1)
        updated.append(line)
    return "\n".join(updated) + "\n"


def prepare(root: Path, unitcell: Path, run_script: Path, pseudo: Path, output: Path) -> None:
    root = root.resolve()
    unitcell = (root / unitcell).resolve() if not unitcell.is_absolute() else unitcell.resolve()
    run_script = (root / run_script).resolve() if not run_script.is_absolute() else run_script.resolve()
    pseudo = (root / pseudo).resolve() if not pseudo.is_absolute() else pseudo.resolve()
    output = (root / output).resolve() if not output.is_absolute() else output.resolve()
    for path in (unitcell, run_script, pseudo):
        if not path.exists():
            raise FileNotFoundError(f"Required path not found: {path}")
    source_archive = root / "source_in_files"
    inputs = sorted(set(root.glob("supercell-*.in")) | set(source_archive.glob("supercell-*.in")))
    if not inputs:
        raise FileNotFoundError(f"No supercell-*.in files found in {root}")
    template = unitcell.read_text(encoding="utf-8")
    run_text = run_script.read_text(encoding="utf-8")
    jobs = []
    for source in inputs:
        match = re.fullmatch(r"supercell-(\d+)\.in", source.name)
        if not match:
            continue
        number = match.group(1)
        name = f"phonon_{number}"
        folder = output / number
        folder.mkdir(parents=True, exist_ok=True)
        inp_name = source.name
        (folder / inp_name).write_text(merge_input(template, source.read_text(encoding="utf-8"), source), encoding="utf-8")
        shutil.copytree(pseudo, folder / pseudo.name, dirs_exist_ok=True)
        # Point the pw.x invocation at this displacement's input and output.
        script = set_qe_filenames(run_text, inp_name)
        script = set_job_name(script, name)
        (folder / run_script.name).write_text(script, encoding="utf-8")
        jobs.append({"directory": str(folder.relative_to(root)), "input": inp_name, "job_name": name})
        if source.parent != source_archive:
            source_archive.mkdir(parents=True, exist_ok=True)
            shutil.move(str(source), str(source_archive / source.name))
    report = {"created_at_utc": datetime.now(timezone.utc).isoformat(), "unitcell_input": str(unitcell),
              "source_files": [p.name for p in inputs], "source_archive": str(source_archive),
              "output_directory": str(output), "jobs": jobs}
    write_yaml(root / "prepare.yaml", report)
    print(f"Prepared {len(jobs)} displaced calculations in {output}; summary: {root / 'prepare.yaml'}")


def submit(root: Path, output: Path) -> None:
    root = root.resolve()
    output = (root / output).resolve() if not output.is_absolute() else output.resolve()
    if not output.is_dir():
        raise FileNotFoundError(f"Prepared directory not found: {output}. Run prepare first.")
    records = []
    for folder in sorted(p for p in output.iterdir() if p.is_dir() and p.name.isdigit()):
        script = folder / "run_qe.sh"
        if not script.is_file():
            records.append({"directory": str(folder.relative_to(root)), "job_name": "", "job_id": "", "status": "missing run_qe.sh"})
            continue
        content = script.read_text(encoding="utf-8")
        if re.search(r"(?im)^\s*#SBATCH\b", content):
            command = ["sbatch", script.name]
            scheduler = "Slurm"
        elif re.search(r"(?im)^\s*#PBS\b", content) or "PBS_NODEFILE" in content:
            command = ["qsub", script.name]
            scheduler = "PBS"
        else:
            records.append({"directory": str(folder.relative_to(root)), "job_name": "", "job_id": "", "status": "no PBS or Slurm directive"})
            continue
        if not shutil.which(command[0]):
            records.append({"directory": str(folder.relative_to(root)), "job_name": "", "job_id": "", "status": f"{command[0]} not found"})
            continue
        result = subprocess.run(command, cwd=folder, text=True, capture_output=True, check=False)
        output_text = (result.stdout or result.stderr).strip()
        job_id = ""
        if result.returncode == 0:
            job_id = output_text.split()[-1] if output_text else ""
        name_match = re.search(r"(?im)^\s*#(?:SBATCH\s+(?:--job-name=|-J\s+)|PBS\s+-N\s+)(\S+)", content)
        records.append({"directory": str(folder.relative_to(root)), "job_name": name_match.group(1) if name_match else folder.name,
                        "scheduler": scheduler, "job_id": job_id, "status": "submitted" if result.returncode == 0 else "failed",
                        "response": output_text or f"exit code {result.returncode}"})
    write_yaml(root / "submit.yaml", {"submitted_at_utc": datetime.now(timezone.utc).isoformat(), "jobs": records})
    print(f"Recorded {len(records)} jobs in {root / 'submit.yaml'}")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="action")
    prep = sub.add_parser("prepare", help="create ./disp-run/ calculation directories")
    prep.add_argument("--root", type=Path, default=Path("."))
    prep.add_argument("--unitcell", type=Path, help="unit-cell Quantum ESPRESSO input file")
    prep.add_argument("--run-script", type=Path, default=Path("run_qe.sh"))
    prep.add_argument("--pseudo", type=Path, default=Path("pseudo"))
    prep.add_argument("--output", type=Path, default=Path("disp-run"))
    subm = sub.add_parser("submit", help="submit prepared PBS or Slurm jobs")
    subm.add_argument("--root", type=Path, default=Path("."))
    subm.add_argument("--output", type=Path, default=Path("disp-run"))
    args = parser.parse_args()
    try:
        if args.action == "prepare":
            unitcell = args.unitcell or Path(ask("Unit-cell QE input filename"))
            if not unitcell:
                raise ValueError("A unit-cell input filename is required")
            prepare(args.root, unitcell, args.run_script, args.pseudo, args.output)
        elif args.action == "submit":
            submit(args.root, args.output)
        elif args.action is None:
            print("Phonopy + Quantum ESPRESSO preprocessor\n1) Prepare displaced structures\n2) Submit supercell jobs")
            choice = ask("Choose action (1 or 2)")
            root = Path(ask("Working directory", "."))
            if choice == "1":
                unitcell = Path(ask("Unit-cell QE input filename"))
                prepare(root, unitcell, Path(ask("Batch script", "run_qe.sh")), Path(ask("Pseudopotential directory", "pseudo")), Path("disp-run"))
            elif choice == "2":
                submit(root, Path("disp-run"))
            else:
                raise ValueError("Choose 1 or 2")
        else:
            parser.error("unknown action")
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        raise SystemExit(2)


if __name__ == "__main__":
    main()
